SELECT final_selection_id FROM final_strategy_selection WHERE final_selection_id IN
#{id}
ORDER BY final_selection_id FOR UPDATE

mapper.update:
UPDATE strategy_performance
SET actual_sales_qty = #{row.actualSalesQuantity},
    actual_revenue = #{row.actualRevenue},
    actual_contribution_margin = #{row.actualContributionMargin},
    actual_remaining_qty = #{row.actualRemainingQuantity},
    updated_at = SYSTIMESTAMP,
    updated_by = #{actorId}
WHERE strategy_option_id = #{row.strategyOptionId}
  AND performance_date = #{row.performanceDate,jdbcType=DATE}
  AND is_deleted = 0

UPDATE final_strategy_selection SET last_synced_at = #{syncedAt,jdbcType=TIMESTAMP}, updated_at = SYSTIMESTAMP, updated_by = #{actorId} WHERE final_selection_id IN
#{id}
AND is_deleted = 0
